import { useDirection } from '@gentleduck/primitives/direction'
import { useControllableState } from '@gentleduck/primitives/hooks/use-controllable-state'
import * as React from 'react'
import { toDirection } from '../direction/direction.libs'
import type { IComboboxItemProps, IComboboxItemType, IComboboxProps } from './combobox.types'

interface IComboboxContext {
  picked: readonly string[]
  pick: (value: string) => void
}

export const ComboboxContext = React.createContext<IComboboxContext | null>(null)

const toList = (value: string | readonly string[] | undefined): readonly string[] =>
  value === undefined || value === '' ? [] : typeof value === 'string' ? [value] : value

/** What `Combobox` and `MotionCombobox` both keep: the items picked, whether the popover is open, and its direction. */
export function useCombobox(props: IComboboxProps) {
  const { dir, open: openProp, defaultOpen = false, onOpenChange } = props.popover ?? {}
  const direction = useDirection(toDirection(dir))
  const multiple = props.type === 'multiple'
  const [open, setOpen] = useControllableState({
    caller: 'Combobox',
    defaultProp: defaultOpen,
    onChange: onOpenChange,
    prop: openProp,
  })
  const [picked, setPicked] = useControllableState<readonly string[]>({
    caller: 'Combobox',
    defaultProp: toList(props.defaultValue),
    onChange: (next) => {
      if (props.type === 'multiple') props.onValueChange?.([...next])
      else props.onValueChange?.(next[0] ?? '')
    },
    prop: props.value === undefined ? undefined : toList(props.value),
  })

  const pick = React.useCallback(
    (value: string) => {
      setPicked((current) => {
        if (!multiple) return current[0] === value ? [] : [value]
        return current.includes(value) ? current.filter((held) => held !== value) : [...current, value]
      })
      if (!multiple) setOpen(false)
    },
    [multiple, setPicked, setOpen],
  )

  return {
    context: { pick, picked },
    direction,
    labels: picked.map((value) => props.items.find((item) => item.value === value)?.label ?? value),
    multiple,
    open,
    setOpen,
  }
}

/** Whether an item shows as picked, and what picking it does, inside a `Combobox` or out of one. */
export function useComboboxItem({ item, checked, onSelect }: IComboboxItemProps<IComboboxItemType>) {
  const combobox = React.useContext(ComboboxContext)
  const select = React.useCallback(() => {
    combobox?.pick(item.value)
    onSelect?.(item.value)
  }, [combobox, item.value, onSelect])

  return { checked: checked ?? combobox?.picked.includes(item.value) ?? false, select }
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import React from 'react'
import { Badge } from '../badge'
import { Button } from '../button'
import { Checkbox } from '../checkbox'
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '../command'
import { Popover, PopoverContent, PopoverTrigger } from '../popover'
import { Separator } from '../separator'
import { COMBOBOX_MAX_SELECTION_BADGES } from './combobox.constants'
import { ComboboxContext, useCombobox, useComboboxItem } from './combobox.hooks'
import type { IComboboxItemProps, IComboboxItemType, IComboboxProps } from './combobox.types'

const Combobox = React.forwardRef<HTMLButtonElement, IComboboxProps>((props, ref) => {
  const {
    items,
    command,
    commandInput,
    commandEmpty = 'Nothing found.',
    commandTriggerPlaceholder = 'Select item...',
    popoverTrigger,
    popoverContent,
    withSearch = true,
    showSelected = true,
    children,
  } = props
  const { context, direction, labels, multiple, open, setOpen } = useCombobox(props)

  return (
    <ComboboxContext.Provider value={context}>
      <Popover {...props.popover} dir={direction} onOpenChange={setOpen} open={open}>
        <PopoverTrigger asChild>
          <Button ref={ref} {...popoverTrigger} variant={popoverTrigger?.variant ?? 'dashed'}>
            {popoverTrigger?.children}
            {showSelected &&
              (labels.length === 0 ? (
                commandTriggerPlaceholder
              ) : multiple ? (
                <>
                  <Separator orientation="vertical" />
                  <div className="flex gap-1">
                    {labels.length > COMBOBOX_MAX_SELECTION_BADGES ? (
                      <Badge className="rounded-sm px-2 py-0.75 font-normal" variant={'secondary'}>
                        +{labels.length} Selected
                      </Badge>
                    ) : (
                      labels.map((label) => (
                        <Badge className="rounded-[3px] px-2 py-0.5" key={label} variant={'secondary'}>
                          {label}
                        </Badge>
                      ))
                    )}
                  </div>
                </>
              ) : (
                labels[0]
              ))}
          </Button>
        </PopoverTrigger>
        <PopoverContent
          {...popoverContent}
          dir={direction}
          className={cn('w-(--gentleduck-popover-trigger-width) p-0', popoverContent?.className)}>
          <Command {...command}>
            {withSearch && (
              <CommandInput
                {...commandInput}
                className={cn('h-8 px-2 [&_svg:not([class*=size-])]:size-4.5', commandInput?.className)}
              />
            )}
            <CommandList>
              {commandEmpty && <CommandEmpty>{commandEmpty}</CommandEmpty>}
              {children(items)}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </ComboboxContext.Provider>
  )
})
Combobox.displayName = 'Combobox'

const ComboboxGroup = React.forwardRef<
  React.ComponentRef<typeof CommandGroup>,
  React.ComponentPropsWithoutRef<typeof CommandGroup>
>((props, ref) => <CommandGroup ref={ref} {...props} />)
ComboboxGroup.displayName = 'ComboboxGroup'

const ComboboxItem = React.forwardRef<React.ComponentRef<typeof CommandItem>, IComboboxItemProps<IComboboxItemType>>(
  ({ item, onSelect, checked, ...props }, ref) => {
    const state = useComboboxItem({ checked, item, onSelect })
    return (
      <CommandItem
        ref={ref}
        value={item.value}
        aria-checked={state.checked === 'indeterminate' ? 'mixed' : state.checked}
        {...props}
        onSelect={state.select}>
        <Checkbox
          aria-hidden="true"
          checked={state.checked}
          className="pointer-events-none border-foreground/50"
          tabIndex={-1}
        />
        {item.label}
      </CommandItem>
    )
  },
)
ComboboxItem.displayName = 'ComboboxItem'

export { Combobox, ComboboxGroup, ComboboxItem }

import type { Button } from '../button'
import type { Checkbox } from '../checkbox'
import type { Command, CommandInput, CommandItem } from '../command'
import type { Popover, PopoverContent } from '../popover'

/** A single combobox option with a display label and underlying value. */
export interface IComboboxItemType {
  label: string
  value: string
}

interface IComboboxBaseProps {
  /** List of items to display in the combobox. */
  items: readonly IComboboxItemType[]
  /** Whether to show a search input inside the popover. */
  withSearch?: boolean
  /** Whether to display the labels of the picked items in the trigger button. */
  showSelected?: boolean
  /** Props forwarded to the Popover root, its `open`, `defaultOpen` and `onOpenChange` included. */
  popover?: React.ComponentPropsWithoutRef<typeof Popover>
  /** Props forwarded to the trigger Button. */
  popoverTrigger?: React.ComponentPropsWithoutRef<typeof Button>
  /** Props forwarded to PopoverContent. */
  popoverContent?: React.ComponentPropsWithoutRef<typeof PopoverContent>
  /** Props forwarded to the Command root. */
  command?: React.ComponentPropsWithoutRef<typeof Command>
  /** Props forwarded to CommandInput. */
  commandInput?: React.ComponentPropsWithoutRef<typeof CommandInput>
  /** Text in the trigger while nothing is picked. */
  commandTriggerPlaceholder?: string
  /** Message shown when no items match the search query. */
  commandEmpty?: string
  /** Renders the list from the items, as `ComboboxItem` elements. */
  children: (items: readonly IComboboxItemType[]) => React.ReactNode
}

/** Picks one item and closes. Picking it again clears the value to an empty string. */
export interface IComboboxSingleProps extends IComboboxBaseProps {
  type?: 'single'
  /** Controlled value, an empty string when nothing is picked. */
  value?: string
  /** Initial value for uncontrolled usage. */
  defaultValue?: string
  onValueChange?: (value: string) => void
}

/** Picks any number of items, and stays open while it does. */
export interface IComboboxMultipleProps extends IComboboxBaseProps {
  type: 'multiple'
  /** Controlled values. */
  value?: string[]
  /** Initial values for uncontrolled usage. */
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
}

export type IComboboxProps = IComboboxSingleProps | IComboboxMultipleProps

/**
 * Props for an individual combobox item (CommandItem wrapper).
 *
 * @template T - The item type extending `IComboboxItemType`.
 */
export interface IComboboxItemProps<T extends IComboboxItemType = IComboboxItemType>
  extends Omit<React.ComponentPropsWithoutRef<typeof CommandItem>, 'onSelect'> {
  /** The combobox item data. */
  item: T
  /** Called with the item's value when it is picked. */
  onSelect?: (value: T['value']) => void
  /** Whether the item shows as picked. Inside a `Combobox` it follows the combobox's value unless given. */
  checked?: React.ComponentPropsWithoutRef<typeof Checkbox>['checked']
}

